        {
          "check": "follow",
          "matches": "\\b17\\s*(°\\s*)?C\\b|\\b17\\s*degrees?\\s*C|celsius"
        }
      ]
    },
    { "kind": "resume" },
    {
      "kind": "prompt",
      "text": "And what about Porto?",
      "expect": [{ "check": "resume", "tool": "weather__get_weather", "args": { "city": "porto" } }]
    }
  ]
}

